package worldgenlab;

import com.mojang.logging.LogUtils;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.fml.common.Mod;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.server.ServerStoppingEvent;
import org.slf4j.Logger;

/**
 * Development tool, never shipped in the pack. On a local server it opens a web page where sky-island settings can be
 * changed and the resulting terrain viewed in 3D, generated by the game's own worldgen code without touching the world.
 */
@Mod("worldgenlab")
public final class WorldgenLab {
    static final Logger LOG = LogUtils.getLogger();

    public WorldgenLab(IEventBus modBus) {
        NeoForge.EVENT_BUS.addListener(ServerStartedEvent.class, e -> LabHttp.start(e.getServer()));
        NeoForge.EVENT_BUS.addListener(ServerStoppingEvent.class, e -> LabHttp.stop());
    }
}
